from playwright.sync_api import sync_playwright
U="file:///home/claude/meridian/dist/meridian-app.html"
with sync_playwright() as p:
    b=p.chromium.launch()
    pg=b.new_page(viewport={"width":390,"height":844},device_scale_factor=2,color_scheme="light")
    errs=[];pg.on("pageerror",lambda e:errs.append(str(e)))
    pg.goto(U,wait_until="domcontentloaded");pg.wait_for_timeout(400)
    on=lambda:pg.evaluate("[...document.querySelectorAll('.view.on')].map(v=>v.id).join()")
    ov=lambda l:print(l,"|",on(),"| nav hidden:",pg.evaluate("document.getElementById('nav').hidden"),"| ovx:",pg.evaluate("document.documentElement.scrollWidth - window.innerWidth"))
    pg.click("#v-onboarding [data-i=ol]")
    print("msg dot visible:",pg.evaluate("!document.querySelector('#v-home .msgb .dotu').hidden"))
    pg.screenshot(path="p3-home.png")
    pg.click("#v-home .msgb"); pg.wait_for_timeout(100); ov("home->msgs"); pg.screenshot(path="p3-inbox.png")
    print("rows:",pg.evaluate("document.querySelectorAll('#v-msgs .ci').length"),"| unread:",pg.evaluate("document.querySelectorAll('#v-msgs .ci.u').length"),"| req badge:",pg.inner_text("#v-msgs .tb2 i"))
    # requests
    pg.click("#v-msgs .tb2 button >> nth=1"); pg.screenshot(path="p3-requests.png")
    pg.click("#v-msgs [data-ok='1']"); print("intro sent text:",pg.inner_text("#v-msgs .rq .done"),"| badge:",pg.inner_text("#v-msgs .tb2 i"))
    pg.click("#v-msgs [data-no='2']"); print("after decline rows:",pg.evaluate("document.querySelectorAll('#v-msgs .rq').length"))
    pg.screenshot(path="p3-requests-empty.png") if pg.evaluate("document.querySelectorAll('#v-msgs .es').length")==1 else None
    # thread
    pg.click("#v-msgs .tb2 button >> nth=0"); pg.click("#v-msgs .ci >> nth=0"); pg.wait_for_timeout(150); ov("inbox->thread")
    print("bubbles:",pg.evaluate("document.querySelectorAll('#v-thread .bb').length"))
    pg.fill("#v-thread .tin input","Great, let's do Thursday."); pg.press("#v-thread .tin input","Enter"); pg.wait_for_timeout(250)
    print("typing shown:",pg.evaluate("!!document.querySelector('#v-thread .ty')")); pg.screenshot(path="p3-thread.png")
    pg.wait_for_timeout(1500); print("reply arrived, bubbles:",pg.evaluate("document.querySelectorAll('#v-thread .bb').length"),"| last:",pg.inner_text("#v-thread .bb >> nth=-1")[:25])
    pg.click("#v-thread .back"); pg.wait_for_timeout(100); print("unread after reading nia:",pg.evaluate("document.querySelectorAll('#v-msgs .ci.u').length"))
    # profile: message + intro + claim
    pg.click("#nav [data-go=home]"); pg.click("#v-home .ppl .p >> nth=0"); pg.wait_for_timeout(100)
    pg.click("#v-profile [data-thread=ama]"); ov("profile->thread"); print("thread w:",pg.inner_text("#v-thread .hb .t")); pg.click("#v-thread .back")
    pg.click("#v-profile [data-intro=ama]"); pg.wait_for_timeout(450); pg.screenshot(path="p3-intro.png")
    print("send disabled:",pg.is_disabled("#v-intro .sd2"))
    pg.click("#v-intro [data-m=kunle]"); pg.fill("#v-intro textarea","I am raising a seed round for a logistics startup and would love your advice."); print("send disabled after:",pg.is_disabled("#v-intro .sd2"))
    pg.click("#v-intro .sd2"); pg.wait_for_timeout(100); print("intro result:",pg.inner_text("#v-intro h3")); pg.screenshot(path="p3-intro-ok.png")
    pg.click("#v-intro .done2"); print("sheet closed:",pg.evaluate("document.getElementById('v-intro').innerHTML===''"))
    pg.click("#v-profile .note a"); ov("profile->claim"); pg.screenshot(path="p3-claim1.png")
    pg.click("#v-claim [data-m=work]"); pg.click("#v-claim [data-n='2']"); pg.fill("#cl-e","ama@korafreight.com") if False else pg.fill("#v-claim #cl-e","ama@korafreight.com")
    pg.click("#v-claim [data-n='3']"); pg.fill("#v-claim #cl-c","123456"); print("verify enabled:",not pg.is_disabled("#v-claim [data-n='4']")); pg.click("#v-claim [data-n='4']")
    print("claim done:",pg.inner_text("#v-claim h1")); pg.screenshot(path="p3-claim-done.png"); pg.click("#v-claim [data-n='9']"); ov("claim done back")
    # you: edit profile
    pg.click("#nav [data-go=you]"); pg.click("#v-you [data-view=edit]"); pg.wait_for_timeout(100); ov("you->edit"); pg.screenshot(path="p3-edit.png")
    print("save disabled initially:",pg.is_disabled("#v-edit .svb"))
    pg.fill("#v-edit #ef-n","Richard"); pg.fill("#v-edit #ef-h","Founder, Meridian"); pg.fill("#v-edit #ef-b","Building a home for business in Africa.")
    pg.click("#v-edit [data-s='Energy']"); pg.click("#v-edit [data-o='raise']"); pg.click("#v-edit [data-v='Members']")
    print("save enabled:",not pg.is_disabled("#v-edit .svb"),"| count:",pg.inner_text("#v-edit .cnt"))
    pg.click("#v-edit .back"); print("discard prompt:",pg.evaluate("!document.querySelector('#v-edit .dcf').hidden")); pg.screenshot(path="p3-edit-discard.png")
    pg.click("#v-edit [data-d=n]"); pg.click("#v-edit .svb"); pg.wait_for_timeout(200); ov("saved")
    print("you name:",pg.inner_text("#v-you h1"),"|",pg.inner_text("#v-you .hd"),"| chips:",pg.evaluate("[...document.querySelectorAll('#v-you .chips .chip')].map(c=>c.textContent).join(',')"),"| avatar:",pg.inner_text("#v-home .av"))
    pg.click("#v-you [data-view=edit]"); pg.click("#v-edit .back"); print("clean back to:",on())
    # founder
    pg.click("#v-you a[data-view=founder]"); pg.wait_for_timeout(100); ov("you->founder"); pg.screenshot(path="p3-founder.png")
    pg.fill("#v-founder textarea","We signed two new carriers in Tamale this week."); pg.click("#v-founder [data-send]"); print("updates:",pg.evaluate("document.querySelectorAll('#v-founder .up').length"))
    pg.click("#v-founder [data-sub]"); print("checklist:",pg.inner_text("#v-founder .cap >> nth=0"))
    pg.evaluate("window.scrollTo(0,document.body.scrollHeight)"); pg.screenshot(path="p3-founder-bottom.png")
    pg.emulate_media(color_scheme="dark"); pg.wait_for_timeout(150); pg.screenshot(path="p3-founder-dark.png")
    print("ERRORS:",errs)
    b.close()
